import React, { useState, useEffect } from 'react';
import axios from 'axios';
import DashboardLayout from './DashboardLayout';

const ProfilePage = () => {
  const [user, setUser] = useState(JSON.parse(localStorage.getItem('vrx_user') || '{}'));
  const [editing, setEditing] = useState(false);
  const [form, setForm] = useState({ fullName: '', phone: '', studentId: '' });
  const [stats, setStats] = useState({ totalRides: 0, completedRides: 0 });
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState('');

  useEffect(() => {
    if (user._id) {
      axios.get(`http://localhost:5000/api/profile/${user._id}`)
        .then(res => {
          setUser(prev => ({ ...prev, ...res.data.user }));
          setStats(res.data.stats);
          setForm({ fullName: res.data.user.fullName || '', phone: res.data.user.phone || '', studentId: res.data.user.studentId || '' });
        }).catch(console.error);
    }
  }, []);

  const handleSave = async () => {
    setSaving(true);
    try {
      const res = await axios.put(`http://localhost:5000/api/profile/${user._id}`, form);
      const updated = { ...user, ...res.data };
      localStorage.setItem('vrx_user', JSON.stringify(updated));
      setUser(updated);
      setEditing(false);
      setMessage('Profile updated successfully!');
      setTimeout(() => setMessage(''), 3000);
    } catch (err) {
      setMessage('Failed to update profile');
    }
    setSaving(false);
  };

  return (
    <DashboardLayout activeTab="profile">
      <div className="row g-4">
        {/* Profile Card */}
        <div className="col-lg-4">
          <div className="bg-white rounded-4 shadow-sm overflow-hidden">
            <div style={{ height: '120px', background: 'linear-gradient(135deg, #2563EB, #06B6D4)' }}></div>
            <div className="text-center" style={{ marginTop: '-50px' }}>
              <img
                src={`https://ui-avatars.com/api/?name=${encodeURIComponent(user.fullName || 'U')}&background=2563EB&color=fff&size=100&bold=true`}
                className="rounded-circle border border-4 border-white shadow"
                width="100"
                alt="Avatar"
              />
              <h4 className="fw-bold mt-3 mb-1">{user.fullName}</h4>
              <p className="text-muted mb-1"><i className="fa-solid fa-envelope me-2"></i>{user.email}</p>
              <span className="badge bg-primary bg-opacity-10 text-primary px-3 py-2 rounded-pill mb-3">
                <i className="fa-solid fa-shield-halved me-1"></i> {user.role || 'student'}
              </span>
            </div>
            <div className="p-4">
              <div className="d-flex justify-content-around text-center">
                <div>
                  <h5 className="fw-bold text-primary mb-0">{stats.totalRides}</h5>
                  <small className="text-muted">Total Rides</small>
                </div>
                <div style={{ borderLeft: '1px solid #E2E8F0', borderRight: '1px solid #E2E8F0', padding: '0 20px' }}>
                  <h5 className="fw-bold text-success mb-0">{stats.completedRides}</h5>
                  <small className="text-muted">Completed</small>
                </div>
                <div>
                  <h5 className="fw-bold text-info mb-0">₹{user.walletBalance || 0}</h5>
                  <small className="text-muted">Balance</small>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Edit Profile */}
        <div className="col-lg-8">
          <div className="bg-white rounded-4 shadow-sm p-4">
            <div className="d-flex justify-content-between align-items-center mb-4">
              <h5 className="fw-bold m-0"><i className="fa-solid fa-pen-to-square me-2 text-primary"></i>Profile Details</h5>
              {!editing ? (
                <button className="btn btn-outline-primary rounded-pill px-4" onClick={() => setEditing(true)}>
                  <i className="fa-solid fa-edit me-2"></i>Edit
                </button>
              ) : (
                <div className="d-flex gap-2">
                  <button className="btn btn-outline-secondary rounded-pill px-3" onClick={() => setEditing(false)}>Cancel</button>
                  <button className="btn btn-primary-custom rounded-pill px-4" onClick={handleSave} disabled={saving}>
                    {saving ? <><i className="fa-solid fa-spinner fa-spin me-2"></i>Saving...</> : <><i className="fa-solid fa-check me-2"></i>Save</>}
                  </button>
                </div>
              )}
            </div>

            {message && <div className={`alert ${message.includes('success') ? 'alert-success' : 'alert-danger'} py-2`}>{message}</div>}

            <div className="row g-3">
              <div className="col-md-6">
                <label className="form-label fw-bold text-muted small">FULL NAME</label>
                {editing ? (
                  <input type="text" className="form-control p-3 bg-light rounded-3" value={form.fullName} onChange={e => setForm({...form, fullName: e.target.value})} />
                ) : (
                  <p className="form-control-plaintext fs-5">{user.fullName}</p>
                )}
              </div>
              <div className="col-md-6">
                <label className="form-label fw-bold text-muted small">EMAIL</label>
                <p className="form-control-plaintext fs-5 text-muted">{user.email} <i className="fa-solid fa-lock ms-1 small"></i></p>
              </div>
              <div className="col-md-6">
                <label className="form-label fw-bold text-muted small">PHONE NUMBER</label>
                {editing ? (
                  <input type="tel" className="form-control p-3 bg-light rounded-3" placeholder="+91 9876543210" value={form.phone} onChange={e => setForm({...form, phone: e.target.value})} />
                ) : (
                  <p className="form-control-plaintext fs-5">{user.phone || 'Not set'}</p>
                )}
              </div>
              <div className="col-md-6">
                <label className="form-label fw-bold text-muted small">STUDENT ID</label>
                {editing ? (
                  <input type="text" className="form-control p-3 bg-light rounded-3" placeholder="STU-12345" value={form.studentId} onChange={e => setForm({...form, studentId: e.target.value})} />
                ) : (
                  <p className="form-control-plaintext fs-5">{user.studentId || 'Not set'}</p>
                )}
              </div>
              <div className="col-md-6">
                <label className="form-label fw-bold text-muted small">ROLE</label>
                <p className="form-control-plaintext fs-5">{user.role || 'student'}</p>
              </div>
              <div className="col-md-6">
                <label className="form-label fw-bold text-muted small">MEMBER SINCE</label>
                <p className="form-control-plaintext fs-5">{user.createdAt ? new Date(user.createdAt).toLocaleDateString('en-IN', { year: 'numeric', month: 'long', day: 'numeric' }) : 'N/A'}</p>
              </div>
            </div>
